// folk-hiphop pattern in C at 90 BPM
// Front porch intimacy - acoustic-forward, communal warmth
// Minimal electronics, maximum organic feel
setcpm(90)

stack(
  // Drums - hand-clap feel, live room
  s("bd ~ ~ ~, ~ ~ [cp:2 cp:3] ~").room(0.5).gain(0.6),

  // Shaker - steady organic pulse
  s("shaker shaker shaker shaker").gain(0.25).room(0.4),

  // Warm sub - acoustic bass-like
  note("c2 ~ g1 ~, ~ c2 ~ ~").s("sine").lpf(180).attack(0.1).release(0.5).gain(0.55),

  // Harmonica-esque texture
  note("e4 g4").s("sawtooth").lpf(2500).attack(0.3).release(1).room(0.4).gain(0.18),

  // Finger-snap accent
  s("~ ~ ~ ~, ~ rim ~ ~").gain(0.3).room(0.35)
).gain(0.75)

// folk-hiphop pattern in Am at 85 BPM
// Sage Francis-inspired: maximum space for vocal delivery
// Near-minimal production prioritizing message over polish
setcpm(85)

stack(
  // Drums - stripped bare, only essentials
  s("bd ~ ~ ~, ~ ~ [cp:2] ~").room(0.5).gain(0.6),

  // Whisper hi-hat - barely there
  s("~ ~ ~ hh:3").gain(0.25).room(0.3),

  // Deep sub bass - anchor without filling space
  note("a1 ~ ~ ~, ~ ~ a1 ~").s("sine").lpf(150).gain(0.55),

  // Drone pad - creates emotional bed
  note("a2 e3 a3").s("sine").attack(2).release(4).room(0.7).gain(0.2),

  // Ghost melody - hauntingly sparse
  note("e4 ~ ~ ~, ~ ~ ~ c4").s("triangle").delay(0.4).room(0.6).gain(0.15)
).gain(0.7)

// folk-hiphop pattern in Gm at 82 BPM
// Nocturnal introspection - late night walks, urban solitude
// Heavy space, minimal movement, contemplative
setcpm(82)

stack(
  // Drums - sparse, distant
  s("bd ~ ~ ~, ~ ~ ~ ~, ~ ~ cp ~, ~ ~ ~ ~").room(0.7).gain(0.5),

  // Ghost hi-hat - barely there
  s("~ ~ ~ ~, ~ hh:3 ~ ~").room(0.5).gain(0.15),

  // Deep sub - anchoring the night
  note("g1 ~ ~ ~, ~ ~ ~ g1").s("sine").lpf(120).gain(0.5),

  // Foggy pad - urban ambiance
  note("g2 bb2 d3").s("sawtooth").attack(2.5).release(5).lpf(1200).room(0.8).gain(0.2),

  // Distant melody - streetlight reflections
  note("d4 ~ ~ ~, ~ ~ bb3 ~").s("triangle").delay(0.5).room(0.7).gain(0.12)
).gain(0.65)

// folk-hiphop pattern in Em at 88 BPM
// Atmosphere-inspired: warm, organic, slightly underproduced
// Leaves 250-500 Hz space for acoustic guitar overlay
setcpm(88)

stack(
  // Drums - sparse, lazy swing
  s("bd ~ ~ ~, ~ ~ cp ~, ~ hh ~ hh").swing(0.12).room(0.4).gain(0.7),

  // 808 bass - sub with gaps for guitar
  note("e1 ~ ~ e1, ~ e1 ~ ~").s("sine").lpf(200).gain(0.65),

  // Warm texture pad - long attack, sits behind guitar
  note("e3 g3 b3").s("sawtooth").attack(1.5).release(3).lpf(2000).room(0.6).gain(0.25),

  // Subtle melodic dust - sparse, atmospheric
  note("b4 ~ e5 ~, ~ ~ g4 ~").s("triangle").delay(0.35).room(0.5).gain(0.2)
).gain(0.75)

// folk-hiphop pattern in Dm at 92 BPM
// Delta blues meets boom-bap: shuffle groove, bluesy warmth
// Designed for fingerpicking overlay
setcpm(92)

stack(
  // Drums - shuffle hat, solid pocket
  s("bd ~ [~ bd] ~, ~ ~ cp ~, [hh hh:3] [hh hh:5] [hh hh:2] [hh hh:4]").swing(0.18).room(0.35).gain(0.65),

  // Shaker - organic texture
  s("~ shaker ~ shaker").gain(0.2).room(0.4),

  // Bass - walking root notes, bluesy
  note("d2 ~ f2 ~, ~ a2 ~ d2").s("sine").lpf(250).gain(0.6),

  // Warm organ-like chords - church and juke joint
  note("d3 f3 a3, ~ ~ ~, d3 f3 a3, c3 e3 g3").s("sawtooth").lpf(1500).attack(0.5).release(1.5).room(0.5).gain(0.3),

  // Blue notes - pentatonic dust
  note("a4 ~ ~ f4, ~ ~ d4 ~").s("triangle").delay(0.3).room(0.4).gain(0.25)
).gain(0.75)
